class Solution {
public:
    int minimizeArrayValue(vector<int>& nums) {
        long long sum = 0;
        long long ans = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            sum += nums[i];
            long long candidate = (sum + i) / (i + 1);
            if (candidate > ans) ans = candidate;
        }
        return (int)ans;
    }
};
